using System;
using System.Drawing;
using System.Windows.Forms;

namespace OnlyWorkspace.ConfigTool.Services;

public static class AppIconHelper
{
    // Assets\OnlyWorkspace.ico, generated by scripts\generate-assets.py and embedded by the csproj.
    private const string IconResource = "OnlyWorkspace.ConfigTool.AppIcon.ico";

    private static Icon? _cachedIcon;
    private static Icon? _cachedTrayIcon;
    private static readonly object _syncLock = new();

    /// <summary>Multi-resolution application icon (window caption, taskbar, Alt+Tab).</summary>
    public static Icon GetAppIcon()
    {
        lock (_syncLock)
        {
            return _cachedIcon ??= LoadEmbeddedIcon(null);
        }
    }

    /// <summary>
    /// Icon for the notification area, picked at the system small-icon size so it stays crisp at any DPI.
    /// </summary>
    public static Icon GetTrayIcon()
    {
        lock (_syncLock)
        {
            return _cachedTrayIcon ??= LoadEmbeddedIcon(SystemInformation.SmallIconSize);
        }
    }

    private static Icon LoadEmbeddedIcon(Size? size)
    {
        // Icon.ExtractAssociatedIcon is not used: without an icon resource it silently returns the
        // generic Windows executable icon instead of failing.
        using var stream = typeof(AppIconHelper).Assembly.GetManifestResourceStream(IconResource)
            ?? throw new InvalidOperationException($"Missing embedded resource {IconResource}.");
        return size.HasValue ? new Icon(stream, size.Value) : new Icon(stream);
    }
}
